_GRADE_SCALE_EVOLUTION_SCHEMA = "climate-grid/rwc-evolution-v1"
_GRADE_SCALE_EVOLUTION_ITEM_KEYS = ("period", "result")
_GRADE_SCALE_EVOLUTION_OUTPUT_KEYS = (
    "schema",
    "periods",
    "scales",
    "names",
    "pairs",
    "scenarios",
    "data",
)
_GRADE_SCALE_EVOLUTION_ROW_KEYS = (
    "scenario",
    "count",
